import{_ as l,l as i,o as e,c as o,v as t,p as E,x as n,d as s,i as h,S as A}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"指数调仓套利","description":"","frontmatter":{"title":"指数调仓套利","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/index-rebalance-arb.md","filePath":"quant/index-rebalance-arb.md","lastUpdated":1789023840000}'),d={name:"quant/index-rebalance-arb.md"};function p(B,a,c,m,u,_){const r=i("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="指数调仓套利" tabindex="-1">指数调仓套利 <a class="header-anchor" href="#指数调仓套利" aria-label="Permalink to &quot;指数调仓套利&quot;">​</a></h1><div class="epigraph"><p>被动资金必须在生效日把组合推到新权重；宣布日与生效日之间的价格压力，是可预测交易需求的价格，而不是对新基本面的发现。</p><footer>—— 据 Chen, Noronha and Singal, The Price Response to S&amp;P 500 Additions and Deletions, Journal of Finance, 2004；Madhavan, The Russell Reconstitution Effect, Financial Analysts Journal, 2003</footer></div><p>指数不是一张静止的名单。编制规则按市值、流动性、行业配额与可投资性定期审核，成分进出与权重漂移会在事先公布的日历上制造一批<strong>必须成交</strong>的买卖。跟踪该指数的共同基金、ETF 与期货对冲账户，为了把跟踪误差压到合同允许的范围，会在生效日附近集中交易。Chen、Noronha 与 Singal 记录了标普 500 调入调出的价格响应；Madhavan 把罗素年度重组写成可度量的冲击事件；Petajisto 把指数变动视为需求曲线向下倾斜的实验。本篇写的是公开规则下的调仓供需，不是对未公开审核名单的刺探。它与 <a href="/quant/cn-etf-creation">ETF 申赎</a>、<a href="/quant/rebalance-rules">再平衡规则</a> 共享同一条会计：被动者付实施缺口，灵活资本赚的是承接那笔缺口的补偿。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记生效日为 \\(t_e\\)，宣布日为 \\(t_a\\)，通常 \\(t_a\\lt t_e\\)。在 \\(t_a\\) 之后，新名单与新权重对所有人可知。指数产品的目标持仓从旧权重 \\(w^{\\mathrm{old}}\\) 跳到 \\(w^{\\mathrm{new}}\\)，差额 \\(\\Delta w=w^{\\mathrm{new}}-w^{\\mathrm{old}}\\) 必须在某个窗口内完成。若全部被动资金都在 \\(t_e\\) 收盘拍卖吃进 \\(\\Delta w\\)，冲击最大、跟踪误差最小；若提前在 \\([t_a,t_e)\\) 完成，冲击更小，但相对指数的日内偏离会记进跟踪误差。调仓套利要回答的不是「名单会不会变」——规则足够透明时，这几乎是确定性事件——而是：<strong>谁在何时、以何种基准价承担 \\(\\Delta w\\) 的流动性</strong>。</p><p>价格压力有两段。宣布后，预期买家把价格推离旧均衡，这是需求公告；生效日附近，实际成交把临时冲击打进拍卖与尾盘。若调入是永久需求（指数基金将长期持有），价格不必完全回吐，这是向下倾斜需求曲线的含义。若很大一部分成交来自过渡期的杠杆与高频账户，生效日后会有回吐。问题是把「可预测的数量」从「不可预测的信息」里分开：编制规则用的市值与成交额本身与动量、流动性因子纠缠，朴素的「买调入、卖调出」会把这些暴露当成 alpha。</p><h3 id="跟踪误差把被动者钉在日历上" tabindex="-1">跟踪误差把被动者钉在日历上 <a class="header-anchor" href="#跟踪误差把被动者钉在日历上" aria-label="Permalink to &quot;跟踪误差把被动者钉在日历上&quot;">​</a></h3><p>指数产品的合同基准是指数收益，不是到达价。经理可以选择在 \\(t_e\\) 精确复制，把 <a href="/quant/implementation-shortfall">实施缺口</a> 做进基金净值；也可以提前或延后，把缺口换成跟踪误差。大多数产品更怕跟踪误差，因为持有人按相对指数的偏离赎回。于是生效日收盘附近出现一条几乎无弹性的需求曲线。套利方提供的是弹性：在宣布后先买入（或融券卖出调出股），在被动者必须成交时把库存交给他们，赚的是冲击补偿减去库存风险、借券与跟踪对冲成本。</p><p><span class="marginnote">A 股中证、国证与科创 50 / 创业板指的审核有公开日历与入选门槛，但「样本空间」仍受停牌、ST、上市不满期限约束。把美股标普的宣布—生效结构直接套到中证，会漏掉涨跌停与 <a href="/quant/cn-tplus1">T+1</a> 对生效日当天回转的限制。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一条可审计的事件研究应至少分开三个时钟：规则可预测的候选集合（市值门槛附近的名字）、正式宣布、生效与权重生效后的首个完整交易日。对每一只调入（调出）股票，估计被动需求量 \\(\\widehat{Q}_i=\\Delta w_i\\cdot A\\)，其中 \\(A\\) 是跟踪该指数的资产管理规模——来自 ETF 份额、指数基金披露与期货持仓的加总，而不是「全市场市值」。把 \\(\\widehat{Q}_i/\\mathrm{ADV}_i\\) 当作拥挤度，冲击应按 <a href="/quant/sqrt-impact">平方根</a> 或拍卖深度校准，而不是对所有名字用同一个基点。</p><p>交易设计通常有三层，不要混成一个「指数套利」标签。第一层是相对价值：调入股对行业对冲或对指数期货的价差，在 \\([t_a,t_e]\\) 上收敛；这是库存中介。第二层是拍卖与尾盘的流动性提供：在生效日收盘集合承接被动单，见科创与创业板的收盘机制。第三层是权重漂移的日常再平衡——自由流通量调整、配股、停牌复牌——频率更高、单次 \\(\\Delta w\\) 更小，容量来自持续的被动流而不是年度大事件。与 <a href="/quant/index-arb">指数期现</a> 的差别是：期现锁的是期货与篮子的基差，调仓套利锁的是<strong>成分集合变化</strong>带来的个股流量。</p><h3 id="候选集合不是免费的-alpha" tabindex="-1">候选集合不是免费的 alpha <a class="header-anchor" href="#候选集合不是免费的-alpha" aria-label="Permalink to &quot;候选集合不是免费的 alpha&quot;">​</a></h3><p>编制规则若用过去一段时间的日均成交额与自由流通市值，那么靠近门槛的股票在审核窗口内会被交易者自己的成交抬进去——这是反馈。回测若在审核截止日前就把「后来调入」的名字标成多头，是 <a href="/quant/look-ahead-bias">前视</a>：当时可知的只是门槛附近的概率，不是委员会的最终名单。正确的信号是当时可计算的入选概率（距离门槛的距离、停牌状态、配额约束），并显式扣掉借券、涨跌停打不开、以及调出股可能同时被多家产品抛售的拥挤。</p><p>对冲必须声明。买调入、卖指数期货，留下的是调入股相对指数的特异风险，以及期货本身的基差。买调入、卖调出，留下的是两边的特异风险，调出股往往更 illiquid、更可能停牌。行业中性可以去掉编制规则里的行业配额效应，但也会去掉一部分真正的需求冲击——若某行业权重上限导致整组同时被压，那正是事件的一部分。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>经济机制是向下倾斜的剩余需求。被动者在生效日的需求价格弹性接近零，灵活资本的供给弹性决定冲击有多大。冲击的临时部分在生效日后随库存出清而回吐；永久部分对应指数产品将长期持有的那一截。Chen–Noronha–Singal 强调调入与调出不对称：调出后指数基金不再是持有人，但其他投资者的需求曲线未必回到调入前。A 股里停牌与涨跌停把供给弹性进一步切掉，生效日可能出现一字板，名义 \\(\\Delta w\\) 无法在当日完成，剩余量被推到随后若干个交易日，事件窗口被拉长。</p><p>信息机制是次要的。调入可能被解读为「质量认证」，但这解释不了生效日当天相对宣布日的第二段冲击，也解释不了按 \\(\\widehat{Q}/\\mathrm{ADV}\\) 排序的截面：认证应对所有调入相近，流量却差几个数量级。把调仓收益归因成质量因子，会与价值、盈利、规模纠缠；事件研究应按流量标准化，而不是按「是否调入」的 0/1 哑变量。</p><p><span class="marginnote">容量随被动规模上升而先增后减。被动越大，可预测的 \\(Q\\) 越大，中介的期望收入越高；但同一批中介的风险资本有限，生效日的拥挤会把补偿压成负的实施缺口——此时策略变成了与被动者一起挨打。应每年用当时的 \\(A\\) 重估，而不是用十年前的冲击系数。</span></p><h3 id="与因子拥挤、公司行动的边界" tabindex="-1">与因子拥挤、公司行动的边界 <a class="header-anchor" href="#与因子拥挤、公司行动的边界" aria-label="Permalink to &quot;与因子拥挤、公司行动的边界&quot;">​</a></h3><p>自由流通量调整、分红再投资、配股与停牌替换，会在非审核日制造连续的小额 \\(\\Delta w\\)，见 <a href="/quant/corporate-actions">公司行动</a>。它们与年度重组是同一类需求，只是新闻更少、更容易被日度换手淹没。因子组合若与指数权重高度同向，调仓日会同时承受因子再平衡与指数再平衡，见 <a href="/quant/factor-crowding">拥挤</a>。回测应把指数审核日标成事件，而不是把这些天的收益平均进普通的多空夏普。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>名单若来自非公开的委员会判断，公开规则只能给出概率，不能给出确定性交易。把概率当成已实现调入去加杠杆，是把选择偏差写进事件研究。借券、融券标的与 T+1 使调出腿在 A 股更贵、更慢；北向与 ETF 申赎会在生效日前就把一部分 \\(\\Delta w\\) 提前完成，剩余拍卖量小于「ETF 规模乘权重差」的朴素估计。期货与期权的持仓限额、涨跌停，会切断对冲。</p><p>不要把指数调仓写成无风险套利。剩余风险包括：宣布后价格已经部分反映、生效日反向宏观冲击、调入股停牌、跟踪规模 \\(A\\) 估计误差、以及太多人做同一交易。评估应以扣费、扣冲击、扣借券后的事件窗口收益为准，并用 <a href="/quant/capacity-participation">容量</a> 把可交易份额限制在被动流量的一个小比例。预注册窗口与对冲方式，避免在十种对冲里挑出最好的那张表。</p><p><span class="marginnote">ETF 一级市场可以在生效日用篮子申赎转移一部分调仓，而不走二级市场逐股冲击。忽略申赎管道会高估个股拍卖的 \\(Q\\)。方法应同时盯 IOPV、PCF 与二级成交，而不是只盯成分股收盘价。</span></p>',25)),(e(),E(A,null,{default:n(()=>[h(r,{id:"mermaid-73",class:"mermaid",graph:"flowchart%20TD%0A%20%20RULE%5B%22%E7%BC%96%E5%88%B6%E8%A7%84%E5%88%99%E4%B8%8E%E5%AE%A1%E6%A0%B8%E6%97%A5%E5%8E%86%22%5D%20--%3E%20PROB%5B%22%E5%BD%93%E6%97%B6%E5%8F%AF%E8%AE%A1%E7%AE%97%E7%9A%84%E5%85%A5%E9%80%89%E6%A6%82%E7%8E%87%22%5D%0A%20%20PROB%20--%3E%20ANN%5B%22%E5%AE%A3%E5%B8%83%E6%97%A5%20t_a%EF%BC%9A%E5%90%8D%E5%8D%95%E5%85%AC%E5%BC%80%22%5D%0A%20%20ANN%20--%3E%20POS%5B%22%E4%B8%AD%E4%BB%8B%E5%BB%BA%E7%AB%8B%E5%BA%93%E5%AD%98%20%2F%20%E5%AF%B9%E5%86%B2%22%5D%0A%20%20AUM%5B%22%E8%B7%9F%E8%B8%AA%E8%A7%84%E6%A8%A1%20A%22%5D%20--%3E%20Q%5B%22%E8%A2%AB%E5%8A%A8%E9%9C%80%E6%B1%82%20Q%20%3D%20%CE%94w%20%C2%B7%20A%22%5D%0A%20%20ANN%20--%3E%20Q%0A%20%20Q%20--%3E%20EFF%5B%22%E7%94%9F%E6%95%88%E6%97%A5%20t_e%EF%BC%9A%E8%B7%9F%E8%B8%AA%E8%AF%AF%E5%B7%AE%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20POS%20--%3E%20EFF%0A%20%20EFF%20--%3E%20AUC%5B%22%E6%94%B6%E7%9B%98%E6%8B%8D%E5%8D%96%E4%B8%8E%E9%9A%8F%E5%90%8E%E5%87%BA%E6%B8%85%22%5D%0A%20%20AUC%20--%3E%20TMP%5B%22%E4%B8%B4%E6%97%B6%E5%86%B2%E5%87%BB%E5%9B%9E%E5%90%90%22%5D%0A%20%20AUC%20--%3E%20PERM%5B%22%E6%B0%B8%E4%B9%85%E9%9C%80%E6%B1%82%EF%BC%9A%E6%8C%87%E6%95%B0%E9%95%BF%E6%9C%9F%E6%8C%81%E6%9C%89%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>指数调仓套利交易的是公开规则下可预测的被动需求，对象是宣布日与生效日之间的价格压力，不是未公开名单。</li><li>被动产品的跟踪误差约束把需求弹性压到接近零，冲击由灵活资本的供给与 \\(Q/\\mathrm{ADV}\\) 决定。</li><li>信号必须用当时可知的门槛与概率，不能用事后名单；对冲、借券、涨跌停与申赎管道要写进事件研究。</li><li>临时冲击可回吐，永久部分对应指数产品将长期持有的权重；二者不要用同一个 0/1 哑变量去估。</li><li>容量随被动规模与拥挤非线性变化，朴素的历史冲击系数会失效。</li><li>出处：Chen, Noronha and Singal, <em>Journal of Finance</em>, 2004；Madhavan, <em>Financial Analysts Journal</em>, 2003；Petajisto, <em>Financial Analysts Journal</em>, 2011；Shleifer, <em>Journal of Finance</em>, 1986。</li></ul>',2))])}const F=l(d,[["render",p]]);export{D as __pageData,F as default};
